import { createHash } from "node:crypto";
import { expect, it } from "vitest";
import { hashDatasetImportFile } from "../src/control-plane/dataset-import/file-hash.js";

// Synthetic generated bytes prove bounded whole-content hashing above 32-bit file
// offsets. This is not disk/browser transfer, GIS ingestion, or an import receipt.
it("hashes 4 GiB plus a tail against independent native SHA-256 without whole-file allocation", async () => {
  const chunkBytes = 1024 * 1024;
  const totalBytes = 4 * 1024 * 1024 * 1024 + 17;
  const chunk = new Uint8Array(chunkBytes).fill(0x61);
  const native = createHash("sha256");
  let offset = 0;
  let reads = 0;
  const file = {
    size: totalBytes,
    arrayBuffer: () => {
      throw new Error("Whole-file allocation is forbidden");
    },
    slice: (start: number, end: number) => {
      expect(start).toBe(offset);
      expect(end - start).toBeGreaterThan(0);
      expect(end - start).toBeLessThanOrEqual(chunkBytes);
      const bytes = end - start;
      return {
        size: bytes,
        arrayBuffer: async () => {
          const content = bytes === chunkBytes ? chunk : chunk.slice(0, bytes);
          native.update(content);
          offset = end;
          reads++;
          return content.buffer;
        },
      };
    },
  } as unknown as Blob;
  const actual = await hashDatasetImportFile(file, { chunkBytes });
  expect(actual).toBe(native.digest("hex"));
  expect(offset).toBe(totalBytes);
  expect(reads).toBe(4097);
}, 180_000);
